(function(){
  function gen(p){
    p=p||{}; if(!p.domain) return {error:'请填写域名'};
    var s=''; if(p.email) s+='{\n  email '+p.email+'\n}\n\n';
    var block=p.domain + (p.path && p.path!=='/' ? p.path : '');
    s+=block+' {\n';
    if(p.tls==='off') s+='  tls off\n';
    if(p.redir) s+='  redir '+(p.redirTo||'/')+'\n';
    if(p.upstream){ var ups=p.upstream.indexOf(',')>=0? p.upstream.split(/[\s,]+/).filter(Boolean).join(' ') : p.upstream; s+='  reverse_proxy '+ups+'\n'; }
    if(p.fileRoot){ s+='  root * '+p.fileRoot+'\n  file_server\n'; }
    if(p.log) s+='  log\n';
    s+='}\n'; return {value:s};
  }
  var API={gen:gen};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__CaddyForge__=API;
})();
